(30, 1, 'Snoopy', 'perro', 70, 'Macho', 'Mediano', 'si', 'no', 'no', 1, 1, 'Beagle famoso por ser el perro de Charlie Brown.', NULL, NULL, 'mascota_691e404639315_Snoopy.jpg', 2, 3, 1, 2, 0, '2026-01-21 02:45:45', '2026-01-20 02:17:34'),
